	base := firewallIPv4OutputRawRuleBasePath(cur.Name)

	ops = append(ops, diffStringField(base, []string{"action"}, prev.Action, cur.Action)...)

	ops = append(ops, diffStringField(base, []string{"description"}, prev.Description, cur.Description)...)

	ops = append(ops, diffMultiField(base, []string{"dscp"}, prev.Dscp, cur.Dscp)...)

