	ops = append(ops, diffBoolField(base, []string{"disable"}, prev.Disable, cur.Disable)...)

	ops = append(ops, diffBoolField(base, []string{"log"}, prev.Log, cur.Log)...)

	ops = append(ops, diffStringField(base, []string{"protocol"}, prev.Protocol, cur.Protocol)...)

